export const BODY: string = "\n<p>تضمين صورة بصيغة Base64 يبدو انتصارًا مجانيًا. طلب أقل، ولا ملف منفصل تديره، والصورة تظهر لحظة تحميل الصفحة.</p>\n<p>الانتصار حقيقي لكنه ليس مجانيًا. الصورة المضمّنة تكلف ثلثًا إضافيًا من البايتات، ولا يمكن تخزينها مؤقتًا بشكل منفصل، وتجعل كودك أصعب في القراءة والصيانة.</p>\n<p>يقدم هذا المقال إطار القرار: حدود الحجم وحساب التخزين المؤقت والحالات التي يساعد فيها التضمين والحالات التي يضر فيها.</p>\n<h2 id=\"the-embed-decision\">قرار التضمين في فقرة</h2>\n<p>ضمّن الصورة عندما تكون صغيرة وأساسية ومستقرة. أيقونة صغيرة تحتاجها كل صفحة ونادرًا ما تتغير وتكلف طلبًا كاملًا لجلبها منفصلة هي المرشح المثالي.</p>\n<p>اربط الصورة عندما تكون كبيرة أو مشتركة أو متغيرة. الصورة الفوتوغرافية أو الشعار المستخدم في خمسين صفحة أو الصورة التي تُحدَّث أسبوعيًا يجب أن تعيش كملف يخزنه المتصفح مؤقتًا.</p>\n<h2 id=\"size-thresholds\">حدود الحجم: الأرقام</h2>\n<p>أقل من 2 كيلوبايت، ضمّن دون تفكير. الزيادة أقل من كيلوبايت واحد، والطلب الموفر يستحق أكثر بكثير، ولن يلاحظ أي مستخدم التكلفة أبدًا.</p>\n<p>بين 2 و10 كيلوبايت، يبقى التضمين صحيحًا غالبًا. وبين 10 و50 كيلوبايت، قرر حالة بحالة. أما فوق 50 كيلوبايت، فالربط أفضل دائمًا تقريبًا، لأن الزيادة وحدها 16 كيلوبايت أو أكثر.</p>\n<h2 id=\"caching-trade-off\">موازنة التخزين المؤقت</h2>\n<p>التخزين المؤقت هو التكلفة الخفية للتضمين. الصورة المرتبطة تُنزَّل مرة واحدة وتُعاد في كل صفحة تشير إليها، بينما الصورة المضمّنة تُنزَّل من جديد مع كل صفحة.</p>\n<p>فكر في شعار 10 كيلوبايت على موقع من خمسين صفحة. مربوطًا، يكلف 10 كيلوبايت مرة واحدة. مضمّنًا، يكلف 13 كيلوبايت في كل صفحة، أي 650 كيلوبايت في زيارة كاملة. أما زائر الصفحة الواحدة فيدفع التكلفة مرة واحدة فقط.</p>\n<h2 id=\"http-requests-vs-file-size\">الطلبات مقابل البايتات: ما الأغلى</h2>\n<p>كل طلب صورة يكلف رحلة ذهاب وعودة إلى الخادم إضافة إلى مصاريف الاتصال. على اتصال سريع تكون التكلفة صغيرة، لكن على اتصال جوال بطيء قد تهيمن على زمن التحميل.</p>\n<p>التضمين يلغي رحلة الذهاب والعودة تمامًا، لكنه يضيف بايتات إلى HTML نفسه، وHTML يحجب العرض. صفحة فيها ميغابايت من الصور المضمّنة لا يمكن عرضها حتى يُنزَّل كل ذلك. ومع HTTP/2 وHTTP/3 أصبحت الطلبات أرخص، فضعف مبرر التضمين.</p>\n<h2 id=\"icons-and-logos-embed\">الأيقونات والشعارات: ضمّنها</h2>\n<p>الأيقونات هي أفضل مرشح للتضمين. إنها صغيرة، غالبًا أقل من 2 كيلوبايت، وقد تحتاج الصفحة إلى اثنتي عشرة أيقونة، أي اثني عشر طلبًا لو رُبطت.</p>\n<p>الشعارات قرار أدق. شعار صغير أقل من 10 كيلوبايت يظهر في كل صفحة يخسر التخزين المؤقت عند تضمينه، لكن شعارًا في صفحة هبوط واحدة يستحق التضمين. أما الشعار المستخدم في الموقع كله فاربطه.</p>\n<h2 id=\"photos-do-not-embed\">الصور: لا تضمّنها</h2>\n<p>الصور الفوتوغرافية لا يجب تضمينها أبدًا تقريبًا. الصورة النموذجية للويب من 100 إلى 500 كيلوبايت تتحول إلى 130 إلى 670 كيلوبايت كسلسلة، وهذا الوزن يبقى داخل HTML.</p>\n<p>وزن HTML يؤخر العرض، لأن المتصفح يجب أن ينزّل المستند كاملًا قبل عرض أي شيء. والصور تتغير أكثر من الأيقونات، وكل استبدال يعني تعديل الكود الذي يحمل سلسلتها. الاستثناء الوحيد هو مستند الملف الواحد الذي يجب أن يعمل دون اتصال.</p>\n<h2 id=\"css-backgrounds\">خلفيات وأنماط CSS</h2>\n<p>الأنماط الصغيرة المتكررة والقوام مرشحة جيدة للتضمين في CSS. بلاطة 2 كيلوبايت تتكرر كخلفية تكلف قليلًا وتوفر طلبًا في كل صفحة تستخدمها.</p>\n<p>التدرجات والأشكال الزخرفية أفضل كـCSS خالص دون أي صورة. أما صور الخلفية الكبيرة فأبقها مربوطة، لأن صورة رئيسية 200 كيلوبايت تتحول إلى 270 كيلوبايت داخل ورقة الأنماط، وورقة الأنماط تحجب العرض.</p>\n<h2 id=\"html-email\">البريد HTML: ضمّن الصغير واربط الكبير</h2>\n<p>البريد هو المكان الوحيد الذي يكون فيه التضمين ضروريًا غالبًا لا اختياريًا. كثير من العملاء يحجبون الصور البعيدة افتراضيًا، فالصورة المرتبطة قد لا تظهر أبدًا.</p>\n<p>ضمّن الشعار والصور الزخرفية الصغيرة التي تجعل الرسالة معروفة. واربط الصور الكبيرة أو اتركها خارجًا تمامًا، لأن الصورة المضمّنة الثقيلة تجعل الرسالة بطيئة الفتح على الهاتف، وبعض العملاء يرفض الرسائل فوق حد معين.</p>\n<h2 id=\"api-payloads\">حمولات API: Base64 هو المعيار</h2>\n<p>واجهات API عالم مختلف عن صفحات الويب. JSON لا يستطيع حمل بيانات ثنائية، فالصورة التي تسافر داخل حمولة JSON يجب أن تكون Base64، ولا بديل للربط هنا.</p>\n<p>القرار هنا ليس التضمين مقابل الربط، بل هل تنتمي الصورة إلى الحمولة. الصورة الرمزية الصغيرة أو صورة التوقيع تناسب، بينما صورة بعدة ميغابايت تستحق رابطًا غالبًا. واحذر حد حجم الحمولة، واضغط قبل الترميز للاستخدام في API.</p>\n<h2 id=\"measuring-performance\">كيف تقيس الأثر الحقيقي على الأداء</h2>\n<p>الآراء حول التضمين رخيصة، فقِس بنفسك. حمّل الصفحة بالصورة المرتبطة وسجل الزمن، ثم حمّلها بالصورة المضمّنة وقارن.</p>\n<p>اختبر على اتصال جوال بطيء لا على واي فاي المكتب السريع فقط. وراجع الوزن الإجمالي للصفحة في النسختين، وراجع الزيارات المتكررة أيضًا: الزيارة الأولى قد تفضل التضمين، بينما الثانية تفضل الربط لأن الصورة المخزنة لا تكلف شيئًا.</p>\n<h2 id=\"alternatives-to-base64\">بدائل تضمين Base64</h2>\n<p>صور SVG لها خيار أرخص: SVG مرمّز في الرابط. SVG صغير مكتوب مباشرة في رابط بيانات دون Base64 يكون أقصر، لأنه يتجنب الزيادة البالغة 33 بالمئة تمامًا.</p>\n<p>خطوط الأيقونات وأوراق رموز SVG تحل محل كثير من الصور الصغيرة المضمّنة بملف واحد مخزن مؤقتًا. كما أن الإرسال المسبق في HTTP/2 واقتراحات التحميل المسبق تجعل الصور المرتبطة سريعة تقريبًا كالمضمّنة.</p>\n<h2 id=\"security-and-csp\">الأمان وسياسة أمان المحتوى</h2>\n<p>ترويسات سياسة أمان المحتوى قد تحجب روابط البيانات. السياسة الصارمة التي تسمح بالصور من نطاقك فقط سترفض الصورة المضمّنة، فتختفي الصورة دون خطأ واضح.</p>\n<p>إذا كان موقعك يستخدم سياسة صارمة، اسمح بـdata: في توجيه مصدر الصورة أو اربط الصور كملفات. والصور المضمّنة تخفي محتواها أيضًا عن التدقيق البسيط، وللصور المرفوعة من المستخدمين لا تضمّن أبدًا دون فك وترميز وتحقق أولًا.</p>\n<h2 id=\"maintenance-cost\">تكلفة الصيانة التي لا يحسبها أحد</h2>\n<p>الصورة المضمّنة جدار من النص في وسط كودك. تجعل الملفات أصعب في القراءة والمراجعة والبحث، لأن السلسلة لا تعطي أي تلميح عما تُظهره الصورة.</p>\n<p>تحديث صورة مضمّنة يعني العثور على السلسلة واستبدالها والأمل بأنك استبدلت الصحيحة. أما مع الملفات المرتبطة، فالتحديث مجرد تبديل ملف. كما يعاني التحكم في الإصدارات، لأن تغيير سطر واحد في صورة يتحول إلى فرق من ألف سطر.</p>\n<h2 id=\"decision-checklist\">قائمة قرار التضمين</h2>\n<p>اسأل أربعة أسئلة قبل التضمين: هل الصورة أقل من 10 كيلوبايت؟ هل تظهر في صفحة أو بضع صفحات لا في الموقع كله؟ هل تتغير نادرًا؟ هل يجب أن تعمل الصفحة كملف واحد؟</p>\n<p>إذا كانت الإجابات نعم أربع مرات، ضمّنها. وإذا كانت ثلاث نعم وواحدة لا، فكر بعناية. وإذا كانت إجابتان أو أكثر لا، اربط الصورة كملف. ولحمولات API والبريد، القائمة مختلفة لأن التضمين قد يكون إلزاميًا.</p>\n<h2 id=\"revisiting-old-embeds\">كيف تراجع التضمينات القديمة</h2>\n<p>قرارات التضمين تشيخ بشكل سيئ. موقع بدأ كصفحة هبوط واحدة ينمو إلى خمسين صفحة، والشعار المضمّن في كل منها يتحول إلى عبء تخزين مؤقت.</p>\n<p>دقق تضميناتك مرة في السنة. ابحث في الكود عن data:image، واسرد الأحجام، واسأل هل ما زال كل منها يستحق مكانه. إعادة الربط سهلة: احفظ الصورة مفكوكة وارفعها واستبدل السلسلة برابطها.</p>\n<h2 id=\"quick-reference\">مرجع سريع: ضمّن أم اربط</h2>\n<p>ضمّن أيقونات أقل من 2 كيلوبايت والشعارات الصغيرة في الصفحات المنفردة والصور في مستندات الملف الواحد والبريد. الطلب الموفر يستحق أكثر من البايتات المضافة.</p>\n<p>اربط الصور الفوتوغرافية وشعارات الموقع كله وأي شيء فوق 50 كيلوبايت. توفير التخزين المؤقت وسرعة العرض يفوقان توفير الطلبات بكثير. وللترميز، استخدم <a href=\"/ar/tahwil-as-sura-ila-base64/\">محول الصورة إلى Base64</a>، ولعكسه استخدم <a href=\"/ar/tahwil-base64-ila-sura/\">مفكك Base64 إلى صورة</a>. وللسياق الكامل، اقرأ <a href=\"/ar/blog/dalil-tahwil-as-sura-ila-base64/\">الصورة إلى Base64: الدليل الكامل</a> وخطوات <a href=\"/ar/blog/kayfiyya-tahwil-as-sura-ila-base64/\">كيف تحوّل صورة إلى Base64</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"من أي حجم ملف يجب أن أتوقف عن تضمين صور Base64؟","answer":"القاعدة الشائعة هي 10 كيلوبايت: دونها يفوز التضمين غالبًا، وفوق 50 كيلوبايت يفوز الربط دائمًا تقريبًا. بينهما قرر حالة بحالة باستخدام حساب التخزين المؤقت. الصورة في خمسين صفحة تكلف كثيرًا عند تضمينها."},{"question":"هل تضمين صور Base64 يضر بالسيو؟","answer":"قد يضر بسيو الصور، لأن الصور المضمّنة لا تُفهرس ولا تظهر في بحث الصور مثل الملفات المرتبطة. أما سيو الصفحة فالأثر غير مباشر: HTML الأثقل قد يبطئ التحميل ويؤثر في تجربة المستخدم."},{"question":"لماذا يضمّن بعض المطورين كل أيقوناتهم كـBase64؟","answer":"لأن الأيقونات صغيرة وكثيرة، فالتضمين يوفر طلبات كثيرة ببايتات قليلة جدًا. اثنتا عشرة أيقونة 1 كيلوبايت مضمّنة تكلف نحو 16 كيلوبايت إجمالًا وصفر طلبات إضافية. الممارسة منطقية للأيقونات فقط."},{"question":"هل يمكن أن يكسر تضمين Base64 سياسة أمان المحتوى؟","answer":"نعم، السياسة الصارمة التي تسمح بالصور من نطاقات محددة فقط ستحجب روابط البيانات ما لم يُسمح بـdata: صراحة في توجيه img-src. راجع سياستك قبل التضمين، أو اربط الصور كملفات."},{"question":"هل الأفضل تضمين صورة أم استخدام شريط CSS؟","answer":"لمجموعة أيقونات، الشريط أو ورقة رموز SVG أفضل غالبًا، لأنها تُخزَّن مرة واحدة وتخدم كل أيقونة. لأيقونة أو أيقونتين، التضمين أبسط والفرق ضئيل."},{"question":"هل ترميز Base64 يؤثر في جودة الصورة؟","answer":"لا، الترميز قابل للعكس تمامًا ولا يغيّر أي بكسل. سؤال الجودة منفصل: إذا بدت الصورة سيئة بعد التضمين، فالمشكلة في الملف المصدر أو الضغط المطبق قبل الترميز."}];
